import {weeks,sourceInfo} from './curriculum-korean.mjs';
import {gradeLesson,dueReviews,localDay,nextKoreanLesson} from './korean-training.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const all=weeks.flatMap(w=>w.lessons);
const lessonById=id=>all.find(l=>Number(l.id)===Number(id));
const link=(url,text,cls='secondary')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(text)} ↗</a>`;
const button=(action,text,id='',cls='primary')=>`<button class="${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${text}</button>`;
const sourceNote='<p class="source-note">视频与原课程属于トリリンガルのトミ；本站中文导读、例句整理及练习为学习辅助，不是官方试题。课程内容核对于 2026-10-28。发音请跟原声，本页文字题不评估真实发音。</p>';
export function koreanHome(s,dateText){
 const l=lessonById(nextKoreanLesson(s)),due=dueReviews(s),count=s.completed.length,scheduled=Object.values(s.training.reviews).filter(r=>r.due>localDay()).length;
 return `<section class="intro home-intro"><div><span class="eyebrow">JARVAIS · 日本語から韓国語へ</span><h1>今天，从这一步开始。</h1><p>跟一套视频学韩语：看一段，练几题，再把不熟的地方留给明天。</p></div><span class="motto">Never give up</span></section>
 <section class="plan-overview"><div class="plan-top"><h2>你的韩语视频学习进度</h2><a href="#route">查看 43 课路线 ↗</a></div><div class="ko-metrics"><div><strong>${count}<small> / 10</small></strong><span>已完成 · 本次上线</span></div><div><strong>${due.length}</strong><span>今日到期复习题</span></div><div><strong>${scheduled}</strong><span>后续已安排复习题</span></div><div><strong>33</strong><span>后续课程待制作</span></div></div><div class="progress-track" role="progressbar" aria-label="已上线十课完成进度" aria-valuenow="${count*10}" aria-valuemin="0" aria-valuemax="100"><i style="width:${count*10}%"></i></div><p class="step-tip">全套 43 课，本次完成前 10 课的配套训练。按自己的节奏推进，一课可以学几天。</p></section>
 <div class="home-content"><section><h2 class="home-section-title">今日学习<span>${due.length?'先复习，再学新课':'只做一个清晰的小任务'}</span></h2>${due.length?`<div class="ko-review-callout"><div><strong>先用几分钟，找回学过的内容</strong><p>有 ${due.length} 道题到期，错题会优先出现。答完一题看一题解释。</p></div>${button('ko-review','开始今日复习')}</div>`:''}<div class="task-card home-task"><div class="task-top"><span class="pill">${l?`原课程 · 第 ${l.id} 课`:'前十课已完成'}</span><span class="task-meta">${l?esc(l.duration):'继续复习'}</span></div><h2>${l?esc(l.name):'这十课，已经成为你的积累。'}</h2><p class="description">${l?esc(l.concept):'第 11–43 课的本站配套训练待制作。现在可以复习旧课、回看错题，巩固已经学过的内容。'}</p><div class="first-action"><small>${l?'今天的顺序':'接下来'}</small><p>${l?'① 打开原课程 → ② 看中文整理 → ③ 六题巩固 → ④ 明天复习':'打开学习路线回顾前十课，或完成首页到期复习。'}</p></div><div class="task-foot">${button(l?'start':'ko-route',l?'进入今日课程 ↗':'回顾前十课 ↗',l?.id??'')}<small>${l?`${(s.steps[Number(l.id)]??[]).length} / 3 个步骤已完成`:'继续保持学习节奏'}</small></div></div></section>
 <section class="home-notes"><h2 class="home-section-title">学习感想<span>给下次留个起点</span></h2><div class="notes-box"><div class="notes-summary"><span>${s.records.length} 篇视频课感想</span><a href="#records">查看全部 ↗</a></div>${s.records.length?s.records.slice(0,3).map(r=>`<button class="home-note" data-action="open-note" data-id="${esc(r.id)}"><time>${esc(dateText(r.date))}</time><h3>第 ${String(r.lesson).padStart(2,'0')} 课 · ${esc(lessonById(r.lesson)?.name)}</h3><p>${esc(r.text.slice(0,85))}</p></button>`).join(''):'<div class="home-notes-empty"><span class="empty-symbol">✎</span><h3>今天终于弄懂了什么？</h3><p>例如：我能区分日语的「は」和本课 은/는 的用法了。写一句就够。</p></div>'}${button('records','写学习感想 ↗','','secondary')}</div></section></div>
 <div class="home-guide">${due.length?'先做首页到期复习，再进入今日课程。':'完成一次测验后，题目会自动安排到明天复习。'} 记录保存在当前浏览器；换设备请用“数据与备份”。没有完成测验前，点击课程链接不会自动算学完。</div>${sourceNote}`;
}
export function koreanRoute(s){const current=nextKoreanLesson(s);
 return `<div class="page-intro"><span class="eyebrow">TOMI · 43 LESSONS</span><h1>韩语学习路线</h1><p>原课程共 43 课；前 10 课已有本站中文整理与互动巩固。第 1 课先做字母准备；第 7 课可分多天完成。没有固定截止日，学会再继续。</p></div>${weeks.map(w=>`<section class="week-card"><div class="week-head"><span class="week-no">${String(w.n).padStart(2,'0')}</span><div><h2>${esc(w.title)}</h2><p>${esc(w.product)}</p></div><span class="week-progress">${w.lessons.filter(l=>s.completed.includes(Number(l.id))).length} / ${w.lessons.length}</span></div>${w.lessons.map(l=>{const id=Number(l.id),a=s.training.attempts[id],score=a?.submitted?gradeLesson(l,a.answers).score:null;return `<button class="lesson-row ${s.completed.includes(id)?'completed':''} ${id===current?'current':''}" data-action="lesson" data-id="${id}"><span class="lesson-status">${s.completed.includes(id)?'✓':l.id}</span><span><span class="row-title">${esc(l.name)}</span><small>${score===null?'原视频 · 中文整理 · 六题巩固':`最近测验 ${score} 分 · 可重练、查错题`}</small></span>${id===current?'<span class="lesson-tag">当前任务</span>':''}<span class="arrow">↗</span></button>`;}).join('')}</section>`).join('')}<section class="lesson-panel pending-panel"><h2>第 11–43 课 · 配套训练待制作</h2><p>先体验前十课。后面的课暂不安排今日任务，也不能标记完成。</p><details><summary>查看后续 33 课的位置</summary><div class="pending-grid">${Array.from({length:33},(_,i)=>`<div aria-disabled="true"><strong>第 ${String(i+11).padStart(2,'0')} 课</strong><span>待制作</span></div>`).join('')}</div></details></section>${link(sourceInfo.url,'查看原课程介绍')}${sourceNote}`;
}
function choices(q,answers,namePrefix='q'){
 return `<fieldset class="ko-question"><legend>${esc(q.prompt)}</legend>${q.options.map((option,i)=>`<label class="quiz-option"><input type="radio" name="${namePrefix}-${q.id}" value="${i}" ${answers[q.id]===i?'checked':''} required><span><b>${String.fromCharCode(65+i)}</b>${esc(option)}</span></label>`).join('')}</fieldset>`;
}
function quiz(l,s,onlyWrong){const a=s.training.attempts[Number(l.id)],result=a?.submitted?gradeLesson(l,a.answers):null;
 if(!result)return `<form id="ko-quiz-form" data-lesson="${Number(l.id)}"><p class="step-tip">六题都选完再提交；暂存答案会保留在当前浏览器。可以先回看上面的内容。</p>${l.quiz.map((q,i)=>`<div class="question-number">第 ${i+1} / ${l.quiz.length} 题</div>${choices(q,a?.answers??{})}`).join('')}<button class="primary" type="submit">提交测验，查看逐题解释 ✓</button></form>`;
 const wrong=result.items.filter(x=>!x.correct).length;
 return `<div class="quiz-result" role="status"><strong>${result.score}<small> / 100</small></strong><div><h3>${result.score>=80?'本课测验已达标':'再练一次，找回不熟的地方'}</h3><p>答对 ${result.items.length-wrong} / ${result.items.length} 题 · ${wrong} 道错题。复习已加入日程。</p></div></div><div class="quiz-tools">${button('ko-retry','重做本课测验','','secondary')}${button('ko-filter',onlyWrong?'显示全部题目':'只看本次错题','','secondary')}</div>${onlyWrong&&wrong===0?'<p class="ko-no-wrong">这次全部答对。明天再回忆一次，更容易记住。</p>':''}${result.items.filter(x=>!onlyWrong||!x.correct).map(item=>{const q=l.quiz.find(q=>q.id===item.id);return `<article class="answer-explanation ${item.correct?'is-correct':'is-wrong'}"><h3>${item.correct?'✓ 答对':'↺ 需要复习'} · ${esc(q.prompt)}</h3><p>你的答案：<strong>${esc(q.options[item.selected]??'未作答')}</strong>${!item.correct?`<br>正确答案：<strong>${esc(q.options[q.answer])}</strong>`:''}</p><p class="answer-why">${esc(q.explanation)}</p></article>`;}).join('')}`;
}
export function koreanLesson(l,s,onlyWrong=false){const id=Number(l.id),steps=l.action.split('；'),checked=s.steps[id]??[],done=s.completed.includes(id),a=s.training.attempts[id],pass=a?.submitted&&gradeLesson(l,a.answers).score>=80;
 return `${button('today','← 返回今日任务','','back-button')}<div class="lesson-intro"><div><span class="eyebrow">TOMI · 原课程第 ${l.id} 课</span><h1>${esc(l.name)}</h1><p>${esc(l.duration)} · 中文整理＋日语对照＋课后练习</p></div><span class="pill ko-pill">${id} / 10 已上线</span></div>${done?'<div class="completion-banner">✓ 这一课已完成，可以继续回看或重练。</div>':''}<div class="ko-learning-flow"><span>01 看课程</span><i>→</i><span>02 理解重点</span><i>→</i><span>03 做题纠错</span><i>→</i><span>04 明天复习</span></div><div class="lesson-layout"><div>
 <section class="lesson-panel ko-video-panel"><span class="eyebrow">01 · 原课程入口</span><h2>先跟老师学，再回来巩固</h2><p>${esc(l.concept)}</p><div class="video-actions">${link(l.videoUrl,id===1?'打开第 1 课：学习说明':'打开本课视频','primary')}${link(l.sourceUrl,'打开官方图文课程')}</div><p class="step-tip">课程在新标签页打开；看完回到这里即可。视频播放取决于你的网络，官方图文可作为另一入口。</p>${l.prepVideos?`<div class="prep-list"><h3>从零开始，先完成三个准备视频</h3>${l.prepVideos.map(p=>`<div>${link(p.url,p.title)}<small>${esc(p.hint)}</small></div>`).join('')}<p class="step-tip">可以分三天看。下面六题是基础结构巩固，不要求一次掌握全部音变。</p></div>`:''}</section>
 <section class="lesson-panel"><span class="eyebrow">02 · 本站中文整理</span><h2>把今天学到的内容串起来</h2><div class="language-bridge"><span>日本語 N2</span><span>→</span><span>한국어 입문</span><small>借日语理解结构，发音跟韩语原声</small></div>${l.teaching.map(t=>`<section class="mini-teaching"><h3>${esc(t.title)}</h3><p>${esc(t.text)}</p></section>`).join('')}<div class="example-table"><div class="example-head"><span>한국어</span><span>日本語</span><span>中文</span></div>${l.examples.map(x=>`<div><strong lang="ko">${esc(x.ko)}</strong><span lang="ja">${esc(x.ja)}</span><span>${esc(x.zh)}</span></div>`).join('')}</div></section>
 <section class="lesson-panel" id="ko-quiz"><span class="eyebrow">03 · 本站原创配套题</span><h2>六题巩固，检查是不是真的理解了</h2>${quiz(l,s,onlyWrong)}</section>
 <section class="lesson-panel ko-summary"><span class="eyebrow">收好今天的三句话</span><h2>课后总结</h2><ol>${l.summary.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p>提交测验后，题目次日进入复习。复习答错的题隔天再练，答对的题三天后再练。</p>${button('ko-review','查看到期复习','','secondary')}</section>${sourceNote}</div>
 <aside class="lesson-aside"><section class="lesson-panel"><h3>今天只完成这一课</h3><p>完成后再勾选；点击课程链接不会自动勾选。</p>${steps.map((step,i)=>`<label class="step-check ${checked.includes(i)?'done':''}"><input type="checkbox" data-step="${i}" ${checked.includes(i)?'checked':''}><span>${esc(step)}</span></label>`).join('')}<p class="acceptance">六题至少答对五题，再完成三个步骤。</p>${button('ko-complete',done?'这一课已完成 ✓':'完成本课 ✓','','primary').replace('<button ',`<button ${done||checked.length!==3||!pass?'disabled ':''}`)}<p class="step-tip">${pass?'测验已达标。':'先完成测验并达到 80%。'} ${id===10?'前十课结束后继续复习，后续课待制作。':''}</p></section><section class="lesson-panel"><h3>给明天留一句话</h3><div class="field"><label for="lesson-note">今天理解了什么 / 哪里还不熟？</label><textarea id="lesson-note" maxlength="10000" placeholder="例如：四点要用 네 시，不能直接用 사。">${esc(s.drafts[id]??'')}</textarea></div>${button('save-lesson-note','保存为学习感想','','secondary')}<p class="step-tip" id="draft-status">草稿会自动保留。</p></section></aside></div>`;
}
export function koreanReview(s,feedback=null){const due=dueReviews(s),r=due[0];
 if(feedback){const {q,correct,selected}=feedback;return `${button('today','← 返回今日任务','','back-button')}<div class="page-intro"><span class="eyebrow">RECALL · UNDERSTAND · REMEMBER</span><h1>${correct?'这次记住了。':'再理解一次就好。'}</h1><p>答${correct?'对的题三天后再练':'错的题已安排到明天'}，不影响课程完成记录。</p></div><section class="lesson-panel review-focus"><h2>${esc(q.prompt)}</h2><p>你的答案：${esc(q.options[selected])}</p>${!correct?`<p>正确答案：<strong>${esc(q.options[q.answer])}</strong></p>`:''}<div class="concept">${esc(q.explanation)}</div>${button('ko-review-next',due.length?`继续复习 · 还剩 ${due.length} 题`:'今日到期题已完成 ✓')}</section>`;}
 if(!r)return `${button('today','← 返回今日任务','','back-button')}<div class="page-intro"><span class="eyebrow">REVIEW</span><h1>今天的到期题，已经清空。</h1><p>${Object.keys(s.training.reviews).length?'下一批题会按日期自动出现在首页。现在可以继续今日课程，或回看前面学过的内容。':'先完成一课测验，明天这里就会出现对应复习。'}</p></div>${button('today','回到今日学习')}`;
 const l=lessonById(r.lesson),q=l.quiz.find(q=>q.id===r.question);
 return `${button('today','← 返回今日任务','','back-button')}<div class="page-intro"><span class="eyebrow">DAILY REVIEW · ${esc(localDay())}</span><h1>先回忆，再看解释。</h1><p>今天还剩 ${due.length} 道到期题，错题优先。当前来自第 ${l.id} 课：${esc(l.name)}。</p></div><section class="lesson-panel review-focus"><form id="ko-review-form" data-key="${esc(r.key)}">${choices(q,{},'review')}<button type="submit" class="primary">确认答案，查看解释</button></form></section>`;
}
export function archivedKorean(s){const a=s.archive;if(!a)return '';return `<section class="lesson-panel ko-archive"><h2>旧版韩语记录归档</h2><p>之前的独立韩语计划与现在的视频课不同，旧进度和草稿已保留，不计入本套课程完成数。</p><details><summary>查看旧记录 · ${a.records.length} 篇感想 · ${a.completed.length} 课完成</summary>${a.records.map(r=>`<article class="record-item"><h3>旧版第 ${String(r.lesson).padStart(2,'0')} 课</h3><p>${esc(r.text)}</p>${r.blocker?`<p>${esc(r.blocker)}</p>`:''}</article>`).join('')}${Object.entries(a.drafts).filter(([,v])=>v).map(([id,text])=>`<article class="record-item"><h3>旧版第 ${id} 课草稿</h3><p>${esc(text)}</p></article>`).join('')}<p>旧版完成课程：${a.completed.join('、')||'无'}。完整步骤保存在导出备份里。</p></details></section>`;}
